#include "game_engine.hpp"
namespace remora {
int GameEngine::neighbor(int n,int dir)const{int col=(n-1)%3;return n+(col+dir<0||col+dir>2?-dir:dir);}
void GameEngine::whack(){s.total=std::min(28,(int[]){3,5,7,9,12}[s.difficulty]+burden());whackWave();}
void GameEngine::whackWave(){cancel();s.round++;s.purpleDir=s.difficulty>=3?(random()<.5?-1:1):1;s.cues.clear();s.phase=Phase::Whack;int count=(int[]){1,1,2,2,3}[s.difficulty];std::vector<int>reserved;for(int i=0;i<count;i++)for(int tries=0;tries<100;tries++){int type=rnd(s.difficulty==0?2:5),n=key(),target=type==4?neighbor(n,s.purpleDir):n;if(type==4&&((n-1)%3+s.purpleDir<0||(n-1)%3+s.purpleDir>2))continue;if(has(reserved,n)||has(reserved,target))continue;s.cues.push_back({n,target,type});reserved.push_back(n);reserved.push_back(target);break;}int ms=std::max(850,int(std::lround((int[]){2600,2300,1500,1200,1050}[s.difficulty]*pace())));s.window=ms;s.deadline=0;later(ms,[this]{if(s.phase!=Phase::Whack)return;for(auto &c:s.cues)if(c.type==1){c.done=true;points(15);}if(std::all_of(s.cues.begin(),s.cues.end(),[](auto &c){return c.done;}))whackComplete();else fail("ISYARAT TERLEWAT");});}
void GameEngine::whackComplete(){if(s.round>=s.total)clear();else later(140,[this]{whackWave();});}
void GameEngine::whackPress(int n){auto it=std::find_if(s.cues.begin(),s.cues.end(),[n](auto &c){return !c.done&&c.target==n;});if(it==s.cues.end()){fail("TOMBOL TIDAK SESUAI");return;}auto&c=*it;if(c.type==1){fail("MERAH JANGAN DITEKAN");return;}if(c.type==3){fail("KUNING HARUS DITAHAN");return;}if(c.type==2){int ms=(int[]){650,550,360,280,210}[s.difficulty];if(!c.taps){c.taps=1;c.first=s.now;size_t i=it-s.cues.begin();int round=s.round;later(ms,[this,i,round]{if(s.phase==Phase::Whack&&s.round==round&&i<s.cues.size()&&!s.cues[i].done)fail("DOUBLE TAP TERLAMBAT");});return;}if(s.now-c.first>ms){fail("DOUBLE TAP TERLAMBAT");return;}}c.done=true;points(25);if(sound)sound("correct");if(std::all_of(s.cues.begin(),s.cues.end(),[](auto &c){return c.done;}))whackComplete();}
void GameEngine::potato(){s.total=std::min(16,(int[]){2,3,4,5,6}[s.difficulty]+burden());potatoRound();}
void GameEngine::potatoRound(){cancel();s.target=key();s.index=rnd(6);s.dir=s.difficulty==0?1:random()<.5?-1:1;s.steps=0;s.reversed=false;s.green=false;s.phase=Phase::Potato;deadline(std::lround((int[]){15000,12000,9000,8000,7000}[s.difficulty]*std::max(.7f,std::pow(.98f,float(stage())))));potatoTick();}
void GameEngine::potatoTick(){if(s.phase!=Phase::Potato)return;int order[]={1,2,3,6,5,4};s.index=(s.index+s.dir+6)%6;s.signal=order[s.index];s.steps++;if(hard()&&!s.reversed&&s.steps==4){s.dir*=-1;s.reversed=true;}s.green=s.signal==s.target&&!(s.difficulty>=3&&(s.steps/6)%2==0);later(std::max(130,int(std::lround((int[]){650,500,320,230,170}[s.difficulty]*pace()))),[this]{potatoTick();});}
void GameEngine::potatoPress(int n){if(n!=s.target||s.signal!=s.target||!s.green){fail("KENTANG GOSONG");return;}cancel();s.hits++;points(40);if(sound)sound("correct");if(s.hits>=s.total)clear();else{s.phase=Phase::Ready;later(450,[this]{potatoRound();});}}
void GameEngine::direction(){s.total=std::min(24,(int[]){3,4,6,8,10}[s.difficulty]+burden());directionCue();}
void GameEngine::directionCue(){cancel();s.round++;s.rotation=s.difficulty==0?0:rnd(4);s.mirror=s.difficulty>=3&&random()<.5;s.chain.clear();int count=s.difficulty==4?std::min(6,3+extra()):s.difficulty==3&&extra()>0?2:1;for(int i=0;i<count;i++)s.chain.push_back(rnd(4));int base[]={2,3,5,1};for(int i=0;i<4;i++)s.mapping[i]=base[((s.mirror?-i:i)+s.rotation+4)%4];s.chainIndex=0;s.answerWindow=std::max(500,int(std::lround((int[]){6000,4500,1900,1300,950}[s.difficulty]*pace())));s.phase=Phase::DirectionPreview;later((int[]){1200,950,600,450,650}[s.difficulty],[this]{s.phase=Phase::DirectionInput;deadline(s.answerWindow);});}
void GameEngine::directionPress(int n){if(n!=s.mapping[s.chain[s.chainIndex]]){fail("ARAH TERBALIK");return;}s.chainIndex++;points(25);if(sound)sound("correct");if(s.chainIndex==int(s.chain.size())){if(s.round>=s.total)clear();else directionCue();}else deadline(s.answerWindow);}
}
